#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int total_rounds;
    cin >> total_rounds;
    vector<int> alice_moves(total_rounds);
    for (int i = 0; i < total_rounds; ++i) {
        cin >> alice_moves[i];
    }
    vector<int> bob_moves(total_rounds);
    for (int i = 0; i < total_rounds; ++i) {
        cin >> bob_moves[i];
    }

    // Rotate bob_moves by one position to the left
    int first_bob_move = bob_moves[0];
    for (int i = 0; i < total_rounds - 1; ++i) {
        bob_moves[i] = bob_moves[i + 1];
    }
    bob_moves[total_rounds - 1] = first_bob_move;

    int min_wins = 0, max_wins = 0;

    for (int i = 0; i < total_rounds; ++i) {
        min_wins += min(alice_moves[i], bob_moves[i]);
    }

    int max_bob_choice = *max_element(bob_moves.begin(), bob_moves.end());
    for (int i = 0; i < total_rounds; ++i) {
        if (bob_moves[i] == max_bob_choice && bob_moves[i] + alice_moves[i] > min_wins) {
            min_wins = bob_moves[i] + alice_moves[i];
        }
    }

    int max_alice_choice = *max_element(alice_moves.begin(), alice_moves.end());
    for (int i = 0; i < total_rounds; ++i) {
        if (alice_moves[i] == max_alice_choice && alice_moves[i] + bob_moves[i] > min_wins) {
            min_wins = alice_moves[i] + bob_moves[i];
        }
    }

    if (min_wins > total_rounds) {
        min_wins -= total_rounds;
    } else {
        min_wins = 0;
    }

    cout << min_wins << " " << max_wins << "\n";
    return 0;
}
